def solve_v8():
    """
    Rule (v8):
    1. VERTICAL fill: All centers with vertical condition (input[cr-1][cc]==3 and input[cr+1][cc]==3) fill entire column
    2. HORIZONTAL fill: Even-row centers fill entire row OUTWARD to nearest 3; Odd-row centers fill only between center and nearest 3
    """
    d2i = demo2_input

    # Find centers
    centers = []
    for r in range(len(d2i)):
        for c in range(len(d2i[0])):
            if d2i[r][c] != 0 and d2i[r][c] != 3:
                # Check for vertical condition
                if r > 0 and r < len(d2i)-1 and d2i[r-1][c] == 3 and d2i[r+1][c] == 3:
                    centers.append((r, c, d2i[r][c]))

    # Start with 3s
    res = [[0]*len(d2i[0]) for _ in range(len(d2i))]
    for r in range(len(d2i)):
        for c in range(len(d2i[0])):
            if d2i[r][c] == 3:
                res[r][c] = 3

    # Apply vertical fills
    for cr, cc, cv in centers:
        for r in range(len(d2i)):
            if res[r][cc] == 0:
                res[r][cc] = cv

    # Apply horizontal fills
    for cr, cc, cv in centers:
        # Even rows: fill entire row (left/right to nearest 3s)
        # Odd rows: fill only between center and each 3
        if cr % 2 == 0:
            # Fill entire row
            for c in range(len(d2i[0])):
                if res[cr][c] == 0:
                    res[cr][c] = cv
        else:
            # Odd row: fill from center outward to nearest 3 on each side
            # Left side: fill from cc-1 down to first 3 or edge
            for c in range(cc - 1, -1, -1):
                if res[cr][c] == 0:
                    res[cr][c] = cv
                    if d2i[cr][c] == 3:
                        break  # stop at 3
            # Right side: fill from cc+1 to first 3 or edge
            for c in range(cc + 1, len(d2i[0])):
                if res[cr][c] == 0:
                    res[cr][c] = cv
                    if d2i[cr][c] == 3:
                        break  # stop at 3

    return res

