def solve_v10():
    """
    Rule (v10):
    1. VERTICAL fill: All centers with vertical condition fill ENTIRE column (to edges)
    2. HORIZONTAL fill: For each center, find ALL 3s in that row. Fill OUTWARD from center to the boundary 3s (excluding any inner 3s, but continuing through)
    """
    d2i = demo2_input

    # Find all centers
    centers = []
    for r in range(len(d2i)):
        for c in range(len(d2i[0])):
            if d2i[r][c] != 0 and d2i[r][c] != 3:
                if r > 0 and r < len(d2i)-1 and d2i[r-1][c] == 3 and d2i[r+1][c] == 3:
                    centers.append((r, c, d2i[r][c]))

    res = [[0]*10 for _ in range(10)]
    for r in range(10):
        for c in range(10):
            if d2i[r][c] == 3:
                res[r][c] = 3

    # Apply vertical fills
    for cr, cc, cv in centers:
        if d2i[cr-1][cc] == 3 and d2i[cr+1][cc] == 3:
            for r in range(10):
                if res[r][cc] == 0:
                    res[r][cc] = cv

    # Apply horizontal fills: find all 3s in row, use leftmost and rightmost to bound
    for cr, cc, cv in centers:
        all_3s = [c for c in range(10) if d2i[cr][c] == 3]
        if all_3s:
            left_bound = min(all_3s)
            right_bound = max(all_3s)
            # Fill from left_bound to right_bound, excluding 3s themselves
            for c in range(left_bound + 1, right_bound):
                if res[cr][c] == 0:
                    res[cr][c] = cv
            # Also include the center column itself (if it doesn't have a 3)
            if res[cr][cc] == 0:
                res[cr][cc] = cv

    return res

